const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sonoranDesert = ee.Geometry.Polygon(
    [
      [-116.5, 34.5], // Northwest
      [-109.5, 34.5], // Northeast
      [-109.5, 27.0], // Southeast
      [-116.5, 27.0]  // Southwest
    ],
    null,
    false
  );

  const startYear = '2019-01-01';
  const endYear = '2019-12-31';
  const temperatureThresholdC = 75; // degrees Celsius

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('MODIS/061/MOD11A2')
    .filterDate(startYear, endYear)
    .filterBounds(sonoranDesert);

  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No MODIS MOD11A2 images found for 2019 in the Sonoran Desert region.");
    console.log("C1");
    return;
  }
  console.log(`Initial MODIS images for 2019: ${collectionSize}`);

  // 3. Processing
  // Function to mask clouds and scale LST to Celsius
  function processModisLST(image) {
    // Select the LST_Day_1km band and the LST_QA band.
    const lstDay = image.select('LST_Day_1km');
    const qa = image.select('LST_QA');

    // MODIS LST_QA bits:
    // Bits 0-1: LST quality (00 = good quality, 01 = LST produced, other quality, 10 = Emissivity error, 11 = LST not produced due to cloud)
    // Bits 2-3: Emissivity error flag
    // Bits 6-7: Cloud presence (00 = clear, 01 = cloudy, 10 = mixed, 11 = not set)

    // A mask for good quality LST (bits 0-1 == 00).
    const goodQuality = qa.rightShift(0).mod(4).eq(0);

    // A mask for clear sky conditions (bits 6-7 == 00).
    const clearSky = qa.rightShift(6).mod(4).eq(0);

    // Combine masks
    const combinedMask = goodQuality.and(clearSky);

    // Apply the mask and scale LST from Kelvin * 0.02 to Celsius
    const lstCelsius = lstDay.updateMask(combinedMask)
      .multiply(0.02)
      .subtract(273.15)
      .rename('LST_Celsius');

    return image.addBands(lstCelsius);
  }

  const processedCollection = collection.map(processModisLST);

  // Get the maximum LST value for the entire period.
  const maxLSTImage = processedCollection.select('LST_Celsius').max();

  // If there are no valid pixels after processing (e.g., all masked out), maxLSTImage could be null.
  // We need to check for this before reducing.
  if (maxLSTImage.bandNames().length().getInfo() === 0) {
      console.log("No valid LST_Celsius band found after processing (e.g. no images left or no valid pixels).");
      console.log("C2");
      return;
  }

  // Calculate the maximum LST in Celsius within the Sonoran Desert geometry.
  // Use a large scale (e.g., 3000m) for region reduction to avoid memory issues and ensure speed.
  const maxLSTResult = await maxLSTImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: sonoranDesert,
    scale: 3000, // MODIS resolution is 1km, so 3km scale is appropriate for speed.
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  // Validate the result
  if (maxLSTResult === null || isNaN(maxLSTResult)) {
    // Check if the calculation resulted in no valid pixels
    const pixelCount = await maxLSTImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: sonoranDesert,
      scale: 3000,
      maxPixels: 1e9
    }).get('LST_Celsius').getInfo();

    if (pixelCount === 0) {
      console.log("No valid pixels remaining after cloud masking and processing for max LST calculation.");
      console.log("C2");
    } else {
      console.log("Max LST calculation failed: result is null or NaN.");
      console.log("C3");
    }
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Maximum Land Surface Temperature in Sonoran Desert (2019): ${maxLSTResult.toFixed(2)} °C`);

  if (maxLSTResult > temperatureThresholdC) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
